WITH base AS MATERIALIZED (
  SELECT text_to_timestamptz_immutable(r.start_time) AS starts, text_to_timestamptz_immutable(r.end_time) AS ends, lower(r.value_text) AS stage
  FROM health_observations_raw r JOIN health_sources s ON s.id=r.source_id
  WHERE r.metric_type='sleep_segment' AND s.source_system='health_sync' AND lower(r.value_text) IN ('light','deep','rem','awake')
    AND text_to_timestamptz_immutable(r.start_time) >= now()-interval '14 days'
), marked AS (
  SELECT *, CASE WHEN starts > lag(ends) OVER (ORDER BY starts,ends)+interval '30 minutes' OR lag(ends) OVER (ORDER BY starts,ends) IS NULL THEN 1 ELSE 0 END AS new_session FROM base
), segmented AS (
  SELECT *, SUM(new_session) OVER (ORDER BY starts,ends) AS session_id FROM marked
), sessions AS (
  SELECT session_id, (MAX(ends) AT TIME ZONE 'America/New_York')::date AS wake_date, SUM(EXTRACT(EPOCH FROM (ends-starts))) FILTER (WHERE stage<>'awake') AS asleep_seconds FROM segmented GROUP BY session_id
), latest AS (
  SELECT session_id FROM sessions ORDER BY wake_date DESC, asleep_seconds DESC LIMIT 1
)
SELECT stage AS "metric", SUM(EXTRACT(EPOCH FROM (ends-starts)))/3600.0 AS "hours"
FROM segmented JOIN latest USING (session_id) GROUP BY stage ORDER BY 2 DESC

WITH recent AS MATERIALIZED (
  SELECT text_to_timestamptz_immutable(r.start_time) AS observed_at, r.value_numeric, r.original_type, s.source_name
  FROM health_observations_raw r JOIN health_sources s ON s.id=r.source_id
  WHERE r.metric_type='steps' AND text_to_timestamptz_immutable(r.start_time) >= $__timeFrom() AND text_to_timestamptz_immutable(r.start_time) <= $__timeTo()
), by_source AS (
  SELECT (observed_at AT TIME ZONE 'America/New_York')::date AS day, source_name, SUM(value_numeric) AS steps FROM recent WHERE original_type='health_sync_steps' GROUP BY 1,2
), daily AS (
  SELECT day, COALESCE(MAX(steps) FILTER (WHERE source_name='Health Sync / Health Connect'), MAX(steps) FILTER (WHERE source_name='Health Sync / Samsung Health')) AS steps FROM by_source GROUP BY day
)
SELECT (date_trunc('week', day::timestamp) AT TIME ZONE 'America/New_York') AS "time", SUM(steps) AS "Steps" FROM daily GROUP BY 1 ORDER BY 1

WITH base AS MATERIALIZED (
  SELECT text_to_timestamptz_immutable(r.start_time) AS starts, text_to_timestamptz_immutable(r.end_time) AS ends, initcap(lower(r.value_text)) AS stage
  FROM health_observations_raw r JOIN health_sources s ON s.id=r.source_id
  WHERE r.metric_type='sleep_segment' AND s.source_system='health_sync' AND lower(r.value_text) IN ('light','deep','rem','awake') AND text_to_timestamptz_immutable(r.start_time)>=now()-interval '14 days'
), marked AS (
  SELECT *, CASE WHEN starts>lag(ends) OVER (ORDER BY starts,ends)+interval '30 minutes' OR lag(ends) OVER (ORDER BY starts,ends) IS NULL THEN 1 ELSE 0 END AS new_session FROM base
), segmented AS (
  SELECT *, SUM(new_session) OVER (ORDER BY starts,ends) AS session_id FROM marked
), sessions AS (
  SELECT session_id, (MAX(ends) AT TIME ZONE 'America/New_York')::date AS wake_date, SUM(EXTRACT(EPOCH FROM (ends-starts))) FILTER (WHERE stage<>'Awake') AS asleep_seconds FROM segmented GROUP BY session_id
), latest AS (
  SELECT session_id FROM sessions ORDER BY wake_date DESC, asleep_seconds DESC LIMIT 1
)
SELECT starts AS "Start", ends AS "End", stage AS "Sleep Stage" FROM segmented JOIN latest USING (session_id) ORDER BY starts

WITH base AS MATERIALIZED (
  SELECT text_to_timestamptz_immutable(r.start_time) AS starts, text_to_timestamptz_immutable(r.end_time) AS ends, lower(r.value_text) AS stage
  FROM health_observations_raw r JOIN health_sources s ON s.id=r.source_id
  WHERE r.metric_type='sleep_segment' AND s.source_system='health_sync' AND lower(r.value_text) IN ('light','deep','rem','awake') AND text_to_timestamptz_immutable(r.start_time)>=($__timeFrom())::timestamptz-interval '1 day' AND text_to_timestamptz_immutable(r.start_time)<=($__timeTo())::timestamptz
), marked AS (
  SELECT *, CASE WHEN starts>lag(ends) OVER (ORDER BY starts,ends)+interval '30 minutes' OR lag(ends) OVER (ORDER BY starts,ends) IS NULL THEN 1 ELSE 0 END AS new_session FROM base
), segmented AS (
  SELECT *, SUM(new_session) OVER (ORDER BY starts,ends) AS session_id FROM marked
), sessions AS (
  SELECT session_id, (MAX(ends) AT TIME ZONE 'America/New_York')::date AS wake_date, SUM(EXTRACT(EPOCH FROM (ends-starts))) FILTER (WHERE stage<>'awake') AS asleep_seconds, SUM(EXTRACT(EPOCH FROM (ends-starts))) AS tracked_seconds FROM segmented GROUP BY session_id
), ranked AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY wake_date ORDER BY asleep_seconds DESC) AS rank_for_day FROM sessions
)
SELECT (wake_date::timestamp AT TIME ZONE 'America/New_York') AS "time", asleep_seconds/3600.0 AS "Asleep hours", tracked_seconds/3600.0 AS "Tracked hours", 100.0*asleep_seconds/NULLIF(tracked_seconds,0) AS "Efficiency %"
FROM ranked WHERE rank_for_day=1 AND wake_date BETWEEN (($__timeFrom())::timestamptz AT TIME ZONE 'America/New_York')::date AND (($__timeTo())::timestamptz AT TIME ZONE 'America/New_York')::date ORDER BY wake_date

WITH base AS MATERIALIZED (
  SELECT text_to_timestamptz_immutable(r.start_time) AS starts, text_to_timestamptz_immutable(r.end_time) AS ends, lower(r.value_text) AS stage
  FROM health_observations_raw r JOIN health_sources s ON s.id=r.source_id
  WHERE r.metric_type='sleep_segment' AND s.source_system='health_sync' AND lower(r.value_text) IN ('light','deep','rem','awake') AND text_to_timestamptz_immutable(r.start_time)>=($__timeFrom())::timestamptz-interval '1 day' AND text_to_timestamptz_immutable(r.start_time)<=($__timeTo())::timestamptz
), marked AS (
  SELECT *, CASE WHEN starts>lag(ends) OVER (ORDER BY starts,ends)+interval '30 minutes' OR lag(ends) OVER (ORDER BY starts,ends) IS NULL THEN 1 ELSE 0 END AS new_session FROM base
), segmented AS (
  SELECT *, SUM(new_session) OVER (ORDER BY starts,ends) AS session_id FROM marked
), sessions AS (
  SELECT session_id, MIN(starts) AS starts, MAX(ends) AS ends, (MAX(ends) AT TIME ZONE 'America/New_York')::date AS wake_date, SUM(EXTRACT(EPOCH FROM (ends-starts))) FILTER (WHERE stage<>'awake') AS asleep_seconds FROM segmented GROUP BY session_id
), ranked AS (
  SELECT *, ROW_NUMBER() OVER (PARTITION BY wake_date ORDER BY asleep_seconds DESC) AS rank_for_day FROM sessions
)
SELECT starts AT TIME ZONE 'America/New_York' AS "Nap start (ET)", ends AT TIME ZONE 'America/New_York' AS "Nap end (ET)", ROUND((asleep_seconds/3600.0)::numeric,2) AS "Asleep hours"
FROM ranked WHERE rank_for_day>1 AND asleep_seconds>0 AND wake_date BETWEEN (($__timeFrom())::timestamptz AT TIME ZONE 'America/New_York')::date AND (($__timeTo())::timestamptz AT TIME ZONE 'America/New_York')::date ORDER BY starts DESC
